import{_ as e,c as t,o,a3 as i}from"./chunks/framework.Dk6sf0Ip.js";const u=JSON.parse('{"title":"Control de Mantenimiento Planificado","description":"","frontmatter":{},"headers":[],"relativePath":"flows/Mantenimiento/20.0.03_ControldeMantenimientoPlanificado.md","filePath":"flows/Mantenimiento/20.0.03_ControldeMantenimientoPlanificado.md","lastUpdated":1759238350000}'),r={name:"flows/Mantenimiento/20.0.03_ControldeMantenimientoPlanificado.md"};function n(d,a,l,s,c,p){return o(),t("div",null,a[0]||(a[0]=[i('<h1 id="control-de-mantenimiento-planificado" tabindex="-1">Control de Mantenimiento Planificado <a class="header-anchor" href="#control-de-mantenimiento-planificado" aria-label="Permalink to &quot;Control de Mantenimiento Planificado&quot;">​</a></h1><h2 id="objetivo" tabindex="-1">Objetivo <a class="header-anchor" href="#objetivo" aria-label="Permalink to &quot;Objetivo&quot;">​</a></h2><p>El proceso de <strong>Control de Mantenimiento Planificado (CMP)</strong> permite registrar, dar seguimiento y ejecutar tareas de mantenimiento sobre unidades, asegurando su trazabilidad y priorización dentro del sistema.</p><h2 id="pantalla-principal-detalle-de-la-solicitud" tabindex="-1">Pantalla Principal: Detalle de la Solicitud <a class="header-anchor" href="#pantalla-principal-detalle-de-la-solicitud" aria-label="Permalink to &quot;Pantalla Principal: Detalle de la Solicitud&quot;">​</a></h2><p>Esta pantalla se divide en secciones lógicas para garantizar que se capture toda la información necesaria sobre la tarea de mantenimiento.</p><h3 id="_1-datos-de-la-solicitud-identificacion-de-la-tarea" tabindex="-1">1. Datos de la Solicitud (Identificación de la Tarea) <a class="header-anchor" href="#_1-datos-de-la-solicitud-identificacion-de-la-tarea" aria-label="Permalink to &quot;1. Datos de la Solicitud (Identificación de la Tarea)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Campo</th><th>Descripción del Dato</th><th>Notas Importantes</th></tr></thead><tbody><tr><td>ID</td><td>Número interno único de identificación del registro (ejemplo: 18233).</td><td>Generado automáticamente por el sistema. Sirve para referencia interna.</td></tr><tr><td>Solicitud N°</td><td>Número de la solicitud cargada (ejemplo: 475).</td><td>Número de referencia externo o asociado a un formulario de solicitud de mantenimiento previo.</td></tr><tr><td>Fecha que se cargó</td><td>Fecha de creación automática del registro (ejemplo: 26/09/2025).</td><td>Si se cargo en el anterior ya viene cargado.</td></tr><tr><td>Fecha de compromiso</td><td>Fecha límite o prevista de ejecución.</td><td>Se selecciona desde el calendario. Define el target (objetivo) de finalización de la tarea.</td></tr><tr><td>Referencia</td><td>Breve descripción de la tarea (ejemplo: ACOMODAR ZÓCALOS).</td><td>Título corto y descriptivo que permite identificar rápidamente la tarea en listados.</td></tr><tr><td>Unidad</td><td>Unidad o equipo al que corresponde la tarea (ejemplo: OPC575).</td><td>Dato obligatorio. Ingresar todo junto la patente.</td></tr></tbody></table><h3 id="_2-priorizacion-y-responsable" tabindex="-1">2. Priorización y Responsable <a class="header-anchor" href="#_2-priorizacion-y-responsable" aria-label="Permalink to &quot;2. Priorización y Responsable&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Campo</th><th>Descripción del Dato</th><th>Notas Importantes</th></tr></thead><tbody><tr><td>Prioridad</td><td>Nivel de importancia de la solicitud (ejemplo: Alta, Media, Baja).</td><td>Ayuda al planificador a ordenar y asignar recursos. Alta se reserva para tareas críticas que impactan la operación.</td></tr><tr><td>Obs Actuar</td><td>Campo para asignar un responsable o área de seguimiento (ejemplo: Flows Manager).</td><td>Asignación inicial de responsabilidad para la ejecución o seguimiento de la OT.</td></tr></tbody></table><h3 id="_3-notas-detalle-del-trabajo" tabindex="-1">3. Notas (Detalle del Trabajo) <a class="header-anchor" href="#_3-notas-detalle-del-trabajo" aria-label="Permalink to &quot;3. Notas (Detalle del Trabajo)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Campo</th><th>Descripción del Dato</th><th>Notas Importantes</th></tr></thead><tbody><tr><td>Notas</td><td>Detalle de las acciones a realizar (ejemplo: ACOMODAR ZÓCALOS DE ALUMINIO Y COMPRAR TORNILLOS).</td><td>Descripción exhaustiva del trabajo solicitado, incluyendo síntomas, ubicación precisa y cualquier requerimiento especial.</td></tr></tbody></table><h3 id="_4-acciones-disponibles-herramientas-de-soporte" tabindex="-1">4. Acciones Disponibles (Herramientas de Soporte) <a class="header-anchor" href="#_4-acciones-disponibles-herramientas-de-soporte" aria-label="Permalink to &quot;4. Acciones Disponibles (Herramientas de Soporte)&quot;">​</a></h3><h4 id="orden-de-abastecimiento" tabindex="-1">ORDEN DE ABASTECIMIENTO <a class="header-anchor" href="#orden-de-abastecimiento" aria-label="Permalink to &quot;ORDEN DE ABASTECIMIENTO&quot;">​</a></h4><ul><li>Genera un pedido interno de <strong>materiales necesarios</strong> que están en <em>stock</em> en almacén para realizar el mantenimiento</li></ul><h4 id="compras" tabindex="-1">COMPRAS <a class="header-anchor" href="#compras" aria-label="Permalink to &quot;COMPRAS&quot;">​</a></h4><ul><li>Redirige al módulo de compras para <strong>adquirir insumos o repuestos</strong> que <em>no están en stock</em>.</li></ul><h4 id="seleccionar-archivo-para-adjuntar" tabindex="-1">Seleccionar archivo para adjuntar <a class="header-anchor" href="#seleccionar-archivo-para-adjuntar" aria-label="Permalink to &quot;Seleccionar archivo para adjuntar&quot;">​</a></h4><ul><li>Permite agregar documentación o fotos asociadas a la solicitud.</li></ul><h3 id="_5-botones-de-control-navegacion-y-guardado" tabindex="-1">5. Botones de Control (Navegación y Guardado) <a class="header-anchor" href="#_5-botones-de-control-navegacion-y-guardado" aria-label="Permalink to &quot;5. Botones de Control (Navegación y Guardado)&quot;">​</a></h3><p><code>CERRAR</code>Sale de la pantalla <strong>sin guardar cambios</strong>. Úsalo solo para descartar una OT que se haya iniciado por error. Se requiere confirmación para evitar pérdida de dato.</p><p><code>GUARDAR</code> Registra la solicitud en el sistema y mantiene la pantalla actual abierta.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p><strong>Recomendación clave:</strong> Presione <strong>GUARDAR</strong> periódicamente, especialmente después de cargar notas o adjuntar archivos, para asegurar el progreso.</p></div><p><code>SIGUIENTE</code> Proximo paso</p><p><strong>Ejecutar Mantenimiento</strong> -&gt; <a href="./20.2.01-Orden-de-abastecimiento_Markdown.html">Ver mas</a></p><p><strong>Suspender Mantenimiento (Completar observación antes de suspender)</strong> -&gt; Se archiva</p>',25)]))}const h=e(r,[["render",n]]);export{u as __pageData,h as default};
